	it.each([
		["", []],
		["a b\n c", ["a", "b", "c"]],
		[`"two words" 'and more' x"y z"`, ["two words", "and more", "xy z"]],
		[`'' end`, ["", "end"]],
	])("splits %o", (text, expected) => {
		expect(parseArguments(text)).toStrictEqual(expected);
	});
